INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES
('45', 'Garantir a limpeza regular dos acessos e da área afeta à obra, de forma a evitar a acumulação e suspensão de poeiras, quer por ação do vento, quer por ação da circulação de veículos e de equipamentos de obra.', 'EE', 7, 81),
('46', 'Deve ser dada atenção especial à origem/proveniência, e condições de armazenamento, de todos materiais inertes para a construção dos acessos, ou terras de empréstimo se aplicável, não devendo ser provenientes em caso algum, de áreas ocupadas por espécies vegetais exóticas invasoras, para que as mesmas não alterem a ecologia local e introduzam plantas invasoras.', 'EE', 7, 82),
('47', 'Assegurar a não afetação de leito de cheia em resultado da movimentação de máquinas.', 'EE', 8, 83),
('48', 'Garantir as acessibilidades e espaço de estacionamento privilegiado destinado aos organismos afetos ao socorro a envolver em situações de acidente/emergência. Em especial na fase de construção, tendo particular atenção ao eventual aumento do fluxo de transito provocado pela movimentação de veículos afetos as obras, os trabalhos a desenvolver não devem comprometer a operacionalidade das ações de proteção civil e socorro, devendo ser equacionadas alternativas que salvaguardem a passagem de veículos afetos ao socorro e emergência.', 'DO | EE', 8, 84),
('49', 'Seleção preferencial de equipamentos que utilizem fluídos naturais ou gases fluorados com menor potencial de aquecimento global, quando disponíveis.', 'EE', 8, 85),
('50', 'Sempre que a travessia de zonas habitadas for inevitável, deve ser efetuada a velocidade muito reduzida (20 km/h), de forma a minimizar a emissão de poeiras e o incómodo para as populac6es em termos de ruído.', 'EE', 8, 86),
('51', 'Assegurar que as operações de construção mais ruidosas, que se desenrolem na proximidade de recetores sensíveis, apenas podem ocorrer em dias úteis, das 08:00h às 20:00h, não se considerando admissível qualquer extensão do horário de trabalho e das operações de construção.', 'EE', 8, 87),
('52', 'Proceder à manutenção e revisão periódica de todas as máquinas e veículos afetos à obra, de forma a manter as normais condições de funcionamento e assegurar a minimização das emissões gasosas.', 'EE', 8, 88),
('53', 'Assegurar o transporte de materiais de natureza pulverulenta ou do tipo particulado em veículos adequados, com a carga coberta, de forma a impedir a dispersão de poeiras.', 'EE', 8, 89),
('54', 'Verificar periodicamente as condições de segurança dos equipamentos a utilizar durante a execução dos trabalhos, com o objetivo de prevenir eventuais fugas de lubrificantes, combustíveis e emissões gasosas.', 'EE', 8, 90),
('55', 'Proceder à aspersão regular e controlada de água, sobretudo durante os períodos secos e ventosos, nas zonas de trabalhos e nos acessos utilizados pelos diversos veículos, onde poderá ocorrer a produção, acumulação e suspensão de poeiras.', 'EE', 8, 91),
('56', 'Assegurar que os caminhos ou acessos nas imediações da área do projeto não fiquem obstruídos ou em más condições, possibilitando a sua normal utilização por parte da população local. A saída de veículos das zonas de estaleiros e das frentes de obra para a via pública deverá obrigatoriamente ser feita de forma a evitar a sua afetação por arrastamento de terras e lamas pelos rodados dos veículos.', 'EE', 8, 92),
('57', 'Assegurar que são selecionados os métodos construtivos e os equipamentos que originem o menor ruído possível.', 'EE', 8, 93),
('58', 'Garantir a presença em obra unicamente de equipamentos que apresentem homologação acústica nos termos da legislação aplicável e que se encontrem em bom estado de conservação/manutenção.', 'EE', 8, 94),
('59', 'Proceder à manutenção e revisão periódica de todas as máquinas e veículos afetos à obra, de forma a manter as normais condições de funcionamento e assegurar a minimização das emissões gasosas, dos riscos de contaminação dos solos e das águas, e de forma a dar cumprimento às normas relativas à emissão de ruído.', 'EE', 8, 95),
('60', 'Adotar soluções estruturais e construtivas dos órgãos e edifícios, e instalação de sistemas de insonorização dos equipamentos e/ou edifícios que alberguem os equipamentos mais ruidosos, de modo a garantir o cumprimento dos limites estabelecidos no RGR e RRAE.', 'EE', 8, 96),
('61', 'Garantir condições de acessibilidade e operação dos meios de socorro, tanto na fase de construção como de exploração.', 'EE', 8, 97),
('62', 'O armazenamento de produtos/materiais deve ser assegurado em locais apropriados para o efeito. No caso dos produtos perigosos deve ser garantida a construção de uma bacia de retenção, impermeabilizada e isolada da rede de drenagem natural.', 'EE', 9, 98),
('63', 'Os estaleiros e as diferentes frentes de obra devem estar equipados com todos os materiais e meios necessários, que permitam responder em situações de incidentes/acidentes ambientais, nomeadamente derrames de substâncias poluentes.', 'EE', 9, 99),
('64', 'Implementar um adequado sistema de recolha e tratamento de águas residuais, o qual deve ter em atenção as diferentes caraterísticas dos efluentes gerados durante a fase de obra e atender aos seguintes pressupostos:', 'EE', 9, 100);